import Extend from 'flarum/common/extenders';
import app from 'flarum/admin/app';
import CategoryManager from './components/CategoryManager';
import { hasFofWidgets } from '../common/registerFofWidget';
const t = k => app.translator.trans('ernestdefoe-calendar.admin.' + k);

/**
 * `{ id: label }` for a store type, for a multi-select's options. The label
 * is read with `label`, because models name it differently.
 *
 * 🚨 2.3.0 called `model.name()` on groups, and a Group has no name() — it
 * has nameSingular()/namePlural(). The throw took the whole Calendar settings
 * page down with it. Reported by jslirola on discuss.flarum.org.
 */
function options(type, label, keep = () => true) {
  const out = {};
  app.store.all(type).filter(keep).forEach(model => out[model.id()] = label(model));
  return out;
}

/**
 * The ids saved in a list setting, as strings. Reads a JSON list, and also a
 * single id or a comma-separated string, so a value saved by hand or by an
 * older build still shows ticked instead of crashing the page.
 */
function savedIds(raw) {
  let v = raw;
  try {
    v = JSON.parse(String(raw ?? ''));
  } catch (e) {
    // not JSON: a bare "4,5" — split it below
  }
  const list = Array.isArray(v) ? v : String(v ?? '').split(',');
  return list.map(x => String(x).trim()).filter(x => x && x !== 'null');
}

/**
 * A ticked list for "these groups" / "these tags" settings. Core's
 * multi-select is a dropdown, which reads as pick-one (RelicSystem,
 * discuss.flarum.org/d/39377/56); a row of checkboxes says "pick any".
 * Called with `this` = the settings page, so Save and dirty-tracking work
 * through its own setting stream. Saved as a JSON list, like before.
 */
function checkboxList(key, label, help, opts) {
  const id = key.replace(/\W/g, '-');
  return function () {
    const stream = this.setting(key, '[]');
    const selected = savedIds(stream());
    const set = (v, on) => stream(JSON.stringify(on ? [...selected, v] : selected.filter(x => x !== v)));

    // Plain `label.checkbox` rows, as core draws its radio settings; core's
    // Checkbox component is a ✕/✓ toggle, which reads as on/off, not pick-any.
    return m('.Form-group.CalCheckList', {
      role: 'group',
      'aria-labelledby': id
    }, [m('label', {
      id
    }, label), m('.helpText', help), m('.CalCheckList-items', Object.entries(opts()).map(([value, name]) => m('label.checkbox', {
      key: value
    }, [m('input', {
      type: 'checkbox',
      checked: selected.includes(value),
      onchange: e => set(value, e.target.checked)
    }), ' ', name])))]);
  };
}

/*
 * With fof/forum-widgets-core enabled, its widget manager decides where each
 * calendar widget goes (or whether it shows at all), and the sidebar mounts
 * these toggles drive stand aside — so a toggle there would do nothing.
 */
const unlessWidgetCore = config => hasFofWidgets() ? null : config;

// Groups are in the admin payload; tags are not, so ask for them once.
let tagsRequested = false;
function tagOptions() {
  if (!tagsRequested && !app.store.all('tags').length) {
    tagsRequested = true;
    app.store.find('tags').then(() => m.redraw());
  }
  return options('tags', tag => tag.name());
}
